class Solution:
    def rearrangeString(self, s: str, k: int) -> str:
        if k <= 1:
            return s
        from collections import Counter, deque
        import heapq
        counts = Counter(s)
        max_heap = [(-cnt, ch) for ch, cnt in counts.items()]
        heapq.heapify(max_heap)
        cooldown = deque()
        res = []
        while max_heap:
            cnt, ch = heapq.heappop(max_heap)
            res.append(ch)
            cooldown.append((cnt + 1, ch))
            if len(cooldown) >= k:
                ready_cnt, ready_ch = cooldown.popleft()
                if ready_cnt < 0:
                    heapq.heappush(max_heap, (ready_cnt, ready_ch))
        return "".join(res) if len(res) == len(s) else ""

class Solution {
public:
    string rearrangeString(string s, int k) {
        if (k <= 1) return s;
        unordered_map<char, int> counts;
        for (char c : s) counts[c]++;
        priority_queue<pair<int, char>> pq;
        for (const auto& p : counts) pq.push({p.second, p.first});
        queue<pair<int, char>> cooldown;
        string res = "";
        while (!pq.empty()) {
            auto [cnt, ch] = pq.top();
            pq.pop();
            res.push_back(ch);
            cooldown.push({cnt - 1, ch});
            if (cooldown.size() >= static_cast<size_t>(k)) {
                auto ready = cooldown.front();
                cooldown.pop();
                if (ready.first > 0) pq.push(ready);
            }
        }
        return res.size() == s.size() ? res : "";
    }
};

class Solution {
    public String rearrangeString(String s, int k) {
        if (k <= 1) return s;
        Map<Character, Integer> counts = new HashMap<>();
        for (char c : s.toCharArray()) counts.put(c, counts.getOrDefault(c, 0) + 1);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
            pq.offer(new int[]{entry.getValue(), entry.getKey()});
        }
        Queue<int[]> cooldown = new LinkedList<>();
        StringBuilder res = new StringBuilder();
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            res.append((char) cur[1]);
            cur[0]--;
            cooldown.offer(cur);
            if (cooldown.size() >= k) {
                int[] ready = cooldown.poll();
                if (ready[0] > 0) pq.offer(ready);
            }
        }
        return res.length() == s.length() ? res.toString() : "";
    }
}

/**
 * @param {string} s
 * @param {number} k
 * @return {string}
 */
var rearrangeString = function(s, k) {
    if (k <= 1) return s;
    const counts = new Map();
    for (const c of s) counts.set(c, (counts.get(c) || 0) + 1);
    const list = Array.from(counts.entries()).map(([ch, cnt]) => ({ ch, cnt }));
    const cooldown = [];
    const res = [];
    while (list.length > 0) {
        list.sort((a, b) => b.cnt - a.cnt);
        const top = list.shift();
        res.push(top.ch);
        top.cnt--;
        cooldown.push(top);
        if (cooldown.length >= k) {
            const ready = cooldown.shift();
            if (ready.cnt > 0) list.push(ready);
        }
    }
    return res.length === s.length ? res.join('') : '';
};
